session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();
$st=$db->query("SELECT v.id,v.store_name,v.address,v.pincode,v.phone,COUNT(i.id) item_count FROM vendors v LEFT JOIN items i ON i.vendor_id=v.id AND i.available=1 GROUP BY v.id ORDER BY v.store_name");$vendors=$st->fetchAll();
