body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;text-decoration:none;margin-left:18px}.main{max-width:1000px;margin:auto;padding:30px}.hero,.card{background:#fff;border:1px solid #E8E0D0;padding:22px;margin-bottom:18px}.hero{background:#21170B;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:18px}.store{background:#fff;border:1px solid #E8E0D0;padding:18px}.name{font:24px Georgia,serif}.small{font-size:12px;color:#777;line-height:1.6}.btn{display:inline-block;margin-top:12px;background:#C9A84C;color:#1A1108;text-decoration:none;padding:10px 13px;font-size:12px}.note{font-size:12px;color:#777}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="home.php">Home</a><a href="occasions.php">Occasions</a></div><main class="main"><section class="hero"><h1>📍 Store Map & Navigation</h1><p>Browse vendor locations and open directions using the address recorded by the vendor.</p></section><section class="card"><div class="note">This first version uses vendor-provided address and pincode data. Exact distance and map coordinates are not calculated until location coordinates are available.</div></section><div class="grid"><?php foreach($vendors as $v):?><div class="store"><div class="name"><?=htmlspecialchars($v['store_name'])?></div><p class="small">📍 <?=htmlspecialchars($v['address'])?><br>Pincode: <?=htmlspecialchars($v['pincode'])?><br>📞 <?=htmlspecialchars($v['phone']??'Not provided')?><br>👘 <?=intval($v['item_count'])?> available item(s)</p><a class="btn" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=<?=urlencode($v['address'].' '.$v['pincode'])?>">Open Directions</a></div><?php endforeach;?></div></main></body></html>